using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.Data.SqlClient;using MicroEMR.Application.PatientResults;namespace MicroEMR.Api.Controllers;[ApiController,Authorize,Route("api/patients/{patientUid:guid}/results")]public sealed class PatientResultsController:ControllerBase{private readonly IPatientResultRepository r;private readonly ILogger<PatientResultsController>l;public PatientResultsController(IPatientResultRepository x,ILogger<PatientResultsController>y){r=x;l=y;}[HttpGet]public async Task<IActionResult>List(Guid patientUid,string status="New",CancellationToken t=default)=>Ok(await r.List(patientUid,status,t));[HttpGet("{uid:guid}")]public async Task<IActionResult>Get(Guid patientUid,Guid uid,CancellationToken t)=>await r.Get(patientUid,uid,t)is{}x?Ok(x):NotFound();[HttpPost]public async Task<IActionResult>Create(Guid patientUid,CreatePatientResultRequest x,CancellationToken t)=>await M(()=>r.Create(patientUid,x,U(),t),true);[HttpPut("{uid:guid}")]public async Task<IActionResult>Update(Guid patientUid,Guid uid,UpdatePatientResultRequest x,CancellationToken t)=>await M(()=>r.Update(patientUid,uid,x,U(),t));[HttpPost("{uid:guid}/mark-reviewed")]public async Task<IActionResult>Review(Guid patientUid,Guid uid,MarkPatientResultReviewedRequest x,CancellationToken t)=>await M(()=>r.Review(patientUid,uid,x,U(),t));private async Task<IActionResult>M(Func<Task<PatientResultResponse?>>a,bool created=false){try{var x=await a();return x is null?NotFound():created?CreatedAtAction(nameof(Get),new{patientUid=x.PatientUid,uid=x.PatientResultUid},x):Ok(x);}catch(SqlException e)when(e.Number==51302){return Conflict(new{message="Reviewed results cannot be edited."});}catch(Exception e){l.LogError(e,"Patient result operation failed.");return StatusCode(500,new{message="The result operation could not be completed."});}}private long U()=>ClinicalUserActorContext.GetRequired(HttpContext);}
